sed -i 's/wakeWordEngine.wakeWordDetected.collect {/wakeWordEngine.wakeWordDetected.collect {\n                playWakeWordFeedback()\n/g' app/src/main/java/com/example/services/JarvisService.kt
sed -i '/private fun startWakeWordMode()/i \    private fun playWakeWordFeedback() {\n        try {\n            val vibrator = getSystemService(android.content.Context.VIBRATOR_SERVICE) as android.os.Vibrator\n            if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.O) {\n                vibrator.vibrate(android.os.VibrationEffect.createOneShot(100, android.os.VibrationEffect.DEFAULT_AMPLITUDE))\n            } else {\n                @Suppress("DEPRECATION")\n                vibrator.vibrate(100)\n            }\n            val toneGen = android.media.ToneGenerator(android.media.AudioManager.STREAM_MUSIC, 100)\n            toneGen.startTone(android.media.ToneGenerator.TONE_PROP_BEEP, 150)\n        } catch (e: Exception) {\n            Log.e("JarvisService", "Feedback error", e)\n        }\n    }\n' app/src/main/java/com/example/services/JarvisService.kt
